const form = $('Upload CSV').first();
const datasetName = String(form.json.dataset_name || 'unnamed_dataset').trim();
let fileName = 'unknown.csv';
try {
  const bin = form.binary || {};
  const key = Object.keys(bin)[0];
  if (key && bin[key].fileName) fileName = bin[key].fileName;
} catch (e) {}

const items = $input.all();
const issues = [];
let rows = [];

if (items.length === 1 && items[0].json && items[0].json.error) {
  issues.push('CSV could not be parsed: ' + JSON.stringify(items[0].json.error));
} else {
  rows = items.map(i => i.json).filter(r => r && Object.keys(r).length > 0);
}

const columnSet = new Set();
rows.forEach(r => Object.keys(r).forEach(k => columnSet.add(k)));
const columns = Array.from(columnSet);

if (issues.length === 0 && rows.length === 0) issues.push('File contains no data rows.');
if (rows.length > 0 && columns.length === 0) issues.push('No header columns detected.');

const blankHeaders = columns.filter(c => String(c).trim() === '' || /^field\d+$/i.test(c));
if (blankHeaders.length) issues.push('Blank or unnamed header columns: ' + blankHeaders.join(', '));

const normHeaders = {};
columns.forEach(c => {
  const k = String(c).trim().toLowerCase();
  normHeaders[k] = (normHeaders[k] || 0) + 1;
});
const dupHeaders = Object.keys(normHeaders).filter(k => normHeaders[k] > 1);
if (dupHeaders.length) issues.push('Duplicate column names (case-insensitive): ' + dupHeaders.join(', '));

const expectedRaw = String(form.json.expected_columns || '').trim();
const expected = expectedRaw ? expectedRaw.split(',').map(s => s.trim()).filter(Boolean) : [];
const lowerCols = columns.map(c => String(c).trim().toLowerCase());
const missingExpected = expected.filter(e => !lowerCols.includes(e.toLowerCase()));
const unexpected = expected.length ? columns.filter(c => !expected.map(e => e.toLowerCase()).includes(String(c).trim().toLowerCase())) : [];
if (missingExpected.length) issues.push('Missing expected columns: ' + missingExpected.join(', '));

return [{
  json: {
    dataset_name: datasetName,
    file_name: fileName,
    schema_valid: issues.length === 0,
    schema_issues: issues,
    unexpected_columns: unexpected,
    expected_columns: expected,
    columns: columns,
    row_count: rows.length,
    column_count: columns.length,
    rows: rows,
  },
}];

const input = $input.first().json;
const rows = input.rows || [];
const columns = input.columns || [];
const totalCells = rows.length * columns.length;

const isEmpty = v => v === null || v === undefined || (typeof v === 'string' && ['', 'na', 'n/a', 'null', 'none', 'nan', '-'].includes(v.trim().toLowerCase()));
const isNum = v => typeof v === 'number' || (typeof v === 'string' && v.trim() !== '' && !isNaN(Number(v.trim().replace(/,/g, ''))));
const isBool = v => typeof v === 'boolean' || (typeof v === 'string' && ['true', 'false', 'yes', 'no'].includes(v.trim().toLowerCase()));
const isDate = v => typeof v === 'string' && /^\d{4}-\d{1,2}-\d{1,2}|^\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4}/.test(v.trim()) && !isNaN(Date.parse(v.trim().replace(/[.]/g, '/')));
const typeOf = v => (isNum(v) ? 'number' : isBool(v) ? 'boolean' : isDate(v) ? 'date' : 'string');
const toNum = v => (typeof v === 'number' ? v : Number(String(v).trim().replace(/,/g, '')));

// 1. Missing values
const missingByColumn = {};
let missingCells = 0;
columns.forEach(c => {
  const n = rows.filter(r => isEmpty(r[c])).length;
  missingByColumn[c] = n;
  missingCells += n;
});

// 2. Duplicate rows
const seen = {};
let duplicateRows = 0;
const duplicateRowNumbers = [];
rows.forEach((r, idx) => {
  const key = JSON.stringify(columns.map(c => (isEmpty(r[c]) ? '' : String(r[c]).trim().toLowerCase())));
  if (seen[key] !== undefined) {
    duplicateRows++;
    if (duplicateRowNumbers.length < 20) duplicateRowNumbers.push(idx + 2);
  } else {
    seen[key] = idx;
  }
});

// 3. Data type inference + invalid types
const columnTypes = {};
const typeIssuesByColumn = {};
let typeIssues = 0;
columns.forEach(c => {
  const vals = rows.map(r => r[c]).filter(v => !isEmpty(v));
  const counts = { number: 0, boolean: 0, date: 0, string: 0 };
  vals.forEach(v => counts[typeOf(v)]++);
  let dominant = 'string';
  let best = 0;
  Object.keys(counts).forEach(t => { if (counts[t] > best) { best = counts[t]; dominant = t; } });
  columnTypes[c] = vals.length ? dominant : 'empty';
  // a column is typed when >= 70% of values agree on a non-string type
  if (vals.length && dominant !== 'string' && best / vals.length >= 0.7) {
    const bad = vals.length - best;
    if (bad > 0) { typeIssuesByColumn[c] = bad; typeIssues += bad; }
  }
});

// 4. Outliers (IQR method on numeric columns)
const outliersByColumn = {};
let outliers = 0;
let numericCells = 0;
columns.filter(c => columnTypes[c] === 'number').forEach(c => {
  const nums = rows.map(r => r[c]).filter(v => !isEmpty(v) && isNum(v)).map(toNum).sort((a, b) => a - b);
  numericCells += nums.length;
  if (nums.length < 4) return;
  const q = p => { const pos = (nums.length - 1) * p; const lo = Math.floor(pos); const hi = Math.ceil(pos); return nums[lo] + (nums[hi] - nums[lo]) * (pos - lo); };
  const q1 = q(0.25), q3 = q(0.75), iqr = q3 - q1;
  const low = q1 - 1.5 * iqr, high = q3 + 1.5 * iqr;
  const found = nums.filter(n => n < low || n > high);
  if (found.length) {
    outliersByColumn[c] = { count: found.length, lower_bound: Number(low.toFixed(2)), upper_bound: Number(high.toFixed(2)), examples: found.slice(0, 5) };
    outliers += found.length;
  }
});

// 5. Inconsistent categories (same value with different case/spacing)
const categoryIssuesByColumn = {};
let inconsistentCategories = 0;
columns.filter(c => columnTypes[c] === 'string').forEach(c => {
  const vals = rows.map(r => r[c]).filter(v => !isEmpty(v)).map(v => String(v));
  const distinct = new Set(vals);
  if (distinct.size === 0 || distinct.size > Math.max(20, vals.length * 0.5)) return; // not categorical
  const groups = {};
  vals.forEach(v => {
    const k = v.trim().toLowerCase().replace(/\s+/g, ' ');
    groups[k] = groups[k] || {};
    groups[k][v] = (groups[k][v] || 0) + 1;
  });
  const variants = [];
  let affected = 0;
  Object.keys(groups).forEach(k => {
    const forms = Object.keys(groups[k]);
    if (forms.length > 1) {
      const total = forms.reduce((s, f) => s + groups[k][f], 0);
      const top = Math.max.apply(null, forms.map(f => groups[k][f]));
      affected += total - top;
      variants.push(forms.join(' | '));
    }
  });
  if (affected) { categoryIssuesByColumn[c] = { affected_values: affected, variants: variants.slice(0, 10) }; inconsistentCategories += affected; }
});

return [{
  json: {
    dataset_name: input.dataset_name,
    file_name: input.file_name,
    row_count: rows.length,
    column_count: columns.length,
    columns: columns,
    unexpected_columns: input.unexpected_columns || [],
    total_cells: totalCells,
    numeric_cells: numericCells,
    column_types: columnTypes,
    missing_values: missingCells,
    missing_by_column: missingByColumn,
    duplicate_rows: duplicateRows,
    duplicate_row_numbers: duplicateRowNumbers,
    type_issues: typeIssues,
    type_issues_by_column: typeIssuesByColumn,
    outliers: outliers,
    outliers_by_column: outliersByColumn,
    inconsistent_categories: inconsistentCategories,
    category_issues_by_column: categoryIssuesByColumn,
  },
}];

const m = $input.first().json;
const ratio = (bad, total) => (total > 0 ? Math.max(0, 1 - bad / total) : 1);

const dimensions = {
  completeness: ratio(m.missing_values, m.total_cells),
  uniqueness: ratio(m.duplicate_rows, m.row_count),
  validity: ratio(m.type_issues, m.total_cells - m.missing_values),
  consistency: ratio(m.inconsistent_categories, m.total_cells - m.missing_values),
  outlier_free: ratio(m.outliers, m.numeric_cells),
};
const weights = { completeness: 30, uniqueness: 20, validity: 20, consistency: 15, outlier_free: 15 };

let score = 0;
const dimensionScores = {};
Object.keys(weights).forEach(k => {
  dimensionScores[k] = Number((dimensions[k] * 100).toFixed(1));
  score += dimensions[k] * weights[k];
});
score = Number(score.toFixed(1));

const grade = score >= 90 ? 'A' : score >= 80 ? 'B' : score >= 70 ? 'C' : score >= 60 ? 'D' : 'F';
const status = score >= 80 ? 'PASS' : score >= 60 ? 'WARNING' : 'FAIL';

return [{ json: Object.assign({}, m, { quality_score: score, grade: grade, status: status, dimension_scores: dimensionScores }) }];

const r = $input.first().json;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lines = [];
lines.push('DATA QUALITY REPORT - ' + r.dataset_name + ' (' + r.file_name + ')');
lines.push('Score: ' + r.quality_score + '/100 | Grade: ' + r.grade + ' | Status: ' + r.status);
lines.push('Rows: ' + r.row_count + ' | Columns: ' + r.column_count);
lines.push('');
lines.push('Dimension scores: ' + Object.keys(r.dimension_scores).map(k => k + ' ' + r.dimension_scores[k] + '%').join(', '));
lines.push('');
lines.push('Missing values: ' + r.missing_values);
Object.keys(r.missing_by_column).filter(c => r.missing_by_column[c] > 0).forEach(c => lines.push('  - ' + c + ': ' + r.missing_by_column[c]));
lines.push('Duplicate rows: ' + r.duplicate_rows + (r.duplicate_row_numbers.length ? ' (CSV lines ' + r.duplicate_row_numbers.join(', ') + ')' : ''));
lines.push('Invalid data types: ' + r.type_issues);
Object.keys(r.type_issues_by_column).forEach(c => lines.push('  - ' + c + ' (expected ' + r.column_types[c] + '): ' + r.type_issues_by_column[c]));
lines.push('Outliers (IQR): ' + r.outliers);
Object.keys(r.outliers_by_column).forEach(c => { const o = r.outliers_by_column[c]; lines.push('  - ' + c + ': ' + o.count + ' outside [' + o.lower_bound + ', ' + o.upper_bound + '] e.g. ' + o.examples.join(', ')); });
lines.push('Inconsistent categories: ' + r.inconsistent_categories);
Object.keys(r.category_issues_by_column).forEach(c => lines.push('  - ' + c + ': ' + r.category_issues_by_column[c].variants.join('; ')));
if (r.unexpected_columns.length) lines.push('Columns not in expected list: ' + r.unexpected_columns.join(', '));
lines.push('');
lines.push('Column types: ' + Object.keys(r.column_types).map(c => c + '=' + r.column_types[c]).join(', '));

const color = r.status === 'PASS' ? '#1a7f37' : r.status === 'WARNING' ? '#b58100' : '#cf222e';
const html = '<div style="font-family:sans-serif;max-width:720px;margin:auto;text-align:left">' +
  '<h2>Data Quality Report</h2>' +
  '<p style="font-size:28px;color:' + color + ';margin:4px 0"><b>' + r.quality_score + '/100</b> &middot; Grade ' + r.grade + ' &middot; ' + r.status + '</p>' +
  '<pre style="white-space:pre-wrap;background:#f6f8fa;padding:12px;border-radius:6px;font-size:13px">' + esc(lines.join('\n')) + '</pre></div>';

return [{ json: Object.assign({}, r, { report_text: lines.join('\n'), report_html: html }) }];

const report = $input.first().json;
const src = $('Validate Schema').first().json;
const columns = src.columns || [];
const original = src.rows || [];
const types = report.column_types || {};

const MISSING = ['', 'na', 'n/a', 'null', 'none', 'nan', '-', 'not available', 'unknown', '?', 'missing'];
const isMissing = v => v === null || v === undefined || MISSING.includes(String(v).trim().toLowerCase());
const WORDS = { zero: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12, thirteen: 13, fourteen: 14, fifteen: 15, sixteen: 16, seventeen: 17, eighteen: 18, nineteen: 19, twenty: 20 };
const pad = n => (n < 10 ? '0' + n : String(n));

const parseNum = v => {
  if (typeof v === 'number') return v;
  let s = String(v).trim().toLowerCase();
  if (WORDS[s] !== undefined) return WORDS[s];
  s = s.replace(/[$€£₹,\s]/g, '');
  if (s !== '' && !isNaN(Number(s))) return Number(s);
  const u = String(v).trim().toLowerCase().match(/^(-?\d+(?:\.\d+)?)\s*[a-z%]+$/);
  if (u) return Number(u[1]);
  return null;
};
const parseDate = v => {
  const s = String(v).trim();
  let m = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/);
  if (m) { const mo1 = +m[2], d1 = +m[3]; if (mo1 >= 1 && mo1 <= 12 && d1 >= 1 && d1 <= 31) return m[1] + '-' + pad(mo1) + '-' + pad(d1); return null; }
  m = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2,4})$/);
  if (m) {
    let d = +m[1], mo = +m[2], y = +m[3];
    if (y < 100) y += 2000;
    if (mo > 12 && d <= 12) { const t = d; d = mo; mo = t; }
    if (mo >= 1 && mo <= 12 && d >= 1 && d <= 31) return y + '-' + pad(mo) + '-' + pad(d);
    return null;
  }
  const t = Date.parse(s);
  if (!isNaN(t)) { const dt = new Date(t); return dt.getFullYear() + '-' + pad(dt.getMonth() + 1) + '-' + pad(dt.getDate()); }
  return null;
};
const lev = (a, b) => {
  const dp = [];
  for (let i = 0; i <= a.length; i++) { dp[i] = [i]; }
  for (let j = 0; j <= b.length; j++) { dp[0][j] = j; }
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      dp[i][j] = Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
  }
  return dp[a.length][b.length];
};

const stats = { values_trimmed: 0, missing_normalized: 0, numbers_fixed: 0, dates_standardized: 0, invalid_values_cleared: 0, categories_standardized: 0, case_standardized: 0, extreme_outliers_cleared: 0, values_imputed: 0, sparse_rows_removed: 0, duplicates_removed: 0 };
const notes = original.map(() => []);

// Step 1: trim, normalise missing markers, fix types
let rows = original.map((r, i) => {
  const out = {};
  columns.forEach(c => {
    let v = r[c];
    if (typeof v === 'string' && v !== v.trim()) { v = v.trim(); stats.values_trimmed++; }
    if (isMissing(v)) {
      if (v !== '' && v !== null && v !== undefined) { stats.missing_normalized++; }
      out[c] = '';
      return;
    }
    const t = types[c];
    if (t === 'number') {
      const n = parseNum(v);
      if (n === null) { out[c] = ''; stats.invalid_values_cleared++; notes[i].push(c + ' invalid "' + v + '" cleared'); return; }
      if (String(n) !== String(v)) { stats.numbers_fixed++; if (isNaN(Number(String(v).replace(/,/g, '')))) notes[i].push(c + ' "' + v + '" -> ' + n); }
      out[c] = n;
    } else if (t === 'date') {
      const d = parseDate(v);
      if (d === null) { out[c] = ''; stats.invalid_values_cleared++; notes[i].push(c + ' invalid date "' + v + '" cleared'); return; }
      if (d !== v) { stats.dates_standardized++; notes[i].push(c + ' "' + v + '" -> ' + d); }
      out[c] = d;
    } else {
      out[c] = v;
    }
  });
  return out;
});

// Step 2: standardise categories and casing in text columns
columns.filter(c => types[c] === 'string').forEach(c => {
  const vals = rows.map(r => r[c]).filter(v => v !== '');
  if (!vals.length) return;
  const distinct = new Set(vals);
  const upperShare = vals.filter(v => v === String(v).toUpperCase() && /[A-Z]/.test(v)).length / vals.length;
  if (distinct.size > Math.max(20, vals.length * 0.5)) {
    // ID-like / free text: only enforce dominant upper casing
    if (upperShare >= 0.8) rows.forEach((r, i) => { if (r[c] !== '' && r[c] !== String(r[c]).toUpperCase()) { notes[i].push(c + ' "' + r[c] + '" -> uppercase'); r[c] = String(r[c]).toUpperCase(); stats.case_standardized++; } });
    return;
  }
  const groups = {};
  vals.forEach(v => { const k = String(v).toLowerCase().replace(/[-_]+/g, ' ').replace(/\s+/g, ' ').trim(); groups[k] = groups[k] || {}; groups[k][v] = (groups[k][v] || 0) + 1; });
  const canon = {};
  const groupTotals = {};
  Object.keys(groups).forEach(k => {
    const forms = Object.keys(groups[k]);
    forms.sort((a, b) => groups[k][b] - groups[k][a]);
    canon[k] = forms[0];
    groupTotals[k] = forms.reduce((s, f) => s + groups[k][f], 0);
  });
  // map rare typos (<=2 occurrences) to a frequent category within edit distance 2
  const frequent = Object.keys(groupTotals).filter(k => groupTotals[k] >= 3);
  Object.keys(groupTotals).forEach(k => {
    if (groupTotals[k] > 2 || frequent.includes(k) || k.length < 3) return;
    let best = null, bestD = 99;
    frequent.forEach(f => { const d = lev(k, f); if (d < bestD) { bestD = d; best = f; } });
    if (best && bestD <= Math.max(2, Math.floor(best.length / 4))) canon[k] = canon[best];
  });
  rows.forEach((r, i) => {
    if (r[c] === '') return;
    const k = String(r[c]).toLowerCase().replace(/[-_]+/g, ' ').replace(/\s+/g, ' ').trim();
    const target = canon[k];
    if (target !== undefined && target !== r[c]) { notes[i].push(c + ' "' + r[c] + '" -> "' + target + '"'); r[c] = target; stats.categories_standardized++; }
  });
});

// Step 3: clear negatives in positive columns and extreme outliers (beyond 5x IQR)
const medians = {};
columns.filter(c => types[c] === 'number').forEach(c => {
  const allNums = rows.map(r => r[c]).filter(v => v !== '');
  if (allNums.length && allNums.filter(v => v >= 0).length / allNums.length >= 0.95) {
    rows.forEach((r, i) => { if (r[c] !== '' && r[c] < 0) { notes[i].push(c + ' negative ' + r[c] + ' cleared'); r[c] = ''; stats.invalid_values_cleared++; } });
  }
  const nums = rows.map(r => r[c]).filter(v => v !== '').sort((a, b) => a - b);
  if (!nums.length) return;
  const q = p => { const pos = (nums.length - 1) * p; const lo = Math.floor(pos); const hi = Math.ceil(pos); return nums[lo] + (nums[hi] - nums[lo]) * (pos - lo); };
  if (nums.length >= 4) {
    const q1 = q(0.25), q3 = q(0.75), iqr = q3 - q1;
    const low = q1 - 5 * iqr, high = q3 + 5 * iqr;
    rows.forEach((r, i) => { if (r[c] !== '' && iqr > 0 && (r[c] < low || r[c] > high)) { notes[i].push(c + ' extreme outlier ' + r[c] + ' cleared'); r[c] = ''; stats.extreme_outliers_cleared++; } });
  }
  const kept = rows.map(r => r[c]).filter(v => v !== '').sort((a, b) => a - b);
  if (kept.length) { const mid = Math.floor(kept.length / 2); medians[c] = kept.length % 2 ? kept[mid] : (kept[mid - 1] + kept[mid]) / 2; }
});

// Step 4: drop rows that are mostly empty
const keepIdx = [];
rows.forEach((r, i) => {
  const filled = columns.filter(c => r[c] !== '').length;
  if (columns.length && filled / columns.length < 0.5) { stats.sparse_rows_removed++; } else { keepIdx.push(i); }
});

// Step 5: impute remaining gaps (numbers -> median, categories -> "Unknown"; IDs and dates left blank)
const isIdLike = c => { const v = rows.map(r => r[c]).filter(x => x !== ''); return v.length > 0 && new Set(v).size / v.length > 0.9; };
const idCols = columns.filter(c => types[c] === 'string' && isIdLike(c));
keepIdx.forEach(i => {
  const r = rows[i];
  columns.forEach(c => {
    if (r[c] !== '') return;
    if (types[c] === 'number' && medians[c] !== undefined) { r[c] = medians[c]; stats.values_imputed++; notes[i].push(c + ' filled with median ' + medians[c]); }
    else if (types[c] === 'string' && !idCols.includes(c)) { r[c] = 'Unknown'; stats.values_imputed++; notes[i].push(c + ' filled with "Unknown"'); }
  });
});

// Step 6: remove duplicate rows (after cleaning)
const seen = new Set();
const cleaned = [];
keepIdx.forEach(i => {
  const key = JSON.stringify(columns.map(c => String(rows[i][c]).toLowerCase()));
  if (seen.has(key)) { stats.duplicates_removed++; return; }
  seen.add(key);
  const row = Object.assign({}, rows[i]);
  row.dq_notes = notes[i].join('; ');
  cleaned.push(row);
});

const valuesFixed = stats.values_trimmed + stats.missing_normalized + stats.numbers_fixed + stats.dates_standardized + stats.invalid_values_cleared + stats.categories_standardized + stats.case_standardized + stats.extreme_outliers_cleared + stats.values_imputed;
const rowsRemoved = original.length - cleaned.length;
const summaryLines = Object.keys(stats).filter(k => stats[k] > 0).map(k => k.replace(/_/g, ' ') + ': ' + stats[k]);
const cleaningSummary = 'Cleaned ' + original.length + ' -> ' + cleaned.length + ' rows. ' + (summaryLines.length ? summaryLines.join(', ') : 'No changes needed.');
const baseName = String(report.file_name || 'dataset.csv').replace(/\.csv$/i, '');

return [{
  json: Object.assign({}, report, {
    cleaned_rows: cleaned,
    cleaned_row_count: cleaned.length,
    rows_removed: rowsRemoved,
    values_fixed: valuesFixed,
    cleaning_stats: stats,
    cleaning_summary: cleaningSummary,
    cleaned_file_name: baseName + '_cleaned.csv',
  }),
}];
